1568: 		bool prev_4addr = false;
1569: 		bool new_4addr = false;
1570: 
1571: 		vlansdata = IEEE80211_DEV_TO_SUB_IF(params->vlan);
1572: 
1573: 		if (params->vlan->ieee80211_ptr->use_4addr) {
1574: 			if (vlansdata->u.vlan.sta) {
1575: 				err = -EBUSY;
1576: 				goto out_err;
1577: 			}
1578: 
1579: 			rcu_assign_pointer(vlansdata->u.vlan.sta, sta);
1580: 			new_4addr = true;
1581: 		}
1582: 
1583: 		if (sta->sdata->vif.type == NL80211_IFTYPE_AP_VLAN &&
1584: 		    sta->sdata->u.vlan.sta) {
1585: 			RCU_INIT_POINTER(sta->sdata->u.vlan.sta, NULL);
1586: 			prev_4addr = true;
1587: 		}
1588: 
1589: 		sta->sdata = vlansdata;
1590: 
1591: 		if (sta->sta_state == IEEE80211_STA_AUTHORIZED &&
1592: 		    prev_4addr != new_4addr) {
1593: 			if (new_4addr)
1594: 				atomic_dec(&sta->sdata->bss->num_mcast_sta);
1595: 			else
1596: 				atomic_inc(&sta->sdata->bss->num_mcast_sta);
1597: 		}
1598: 
1599: 		cfg80211_send_layer2_update(sta->sdata->dev, sta->sta.addr);
1600: 	}
1601: 
1602: 	err = sta_apply_parameters(local, sta, params);
1603: 	if (err)
1604: 		goto out_err;
1605: 
1606: 	/* When peer becomes authorized, init rate control as well */
1607: 	if (test_sta_flag(sta, WLAN_STA_TDLS_PEER) &&
1608: 	    test_sta_flag(sta, WLAN_STA_AUTHORIZED))
1609: 		rate_control_rate_init(sta);
1610: 
1611: 	mutex_unlock(&local->sta_mtx);
1612: 
1613: 	if ((sdata->vif.type == NL80211_IFTYPE_AP ||
1614: 	     sdata->vif.type == NL80211_IFTYPE_AP_VLAN) &&
1615: 	    sta->known_smps_mode != sta->sdata->bss->req_smps &&
1616: 	    test_sta_flag(sta, WLAN_STA_AUTHORIZED) &&
1617: 	    sta_info_tx_streams(sta) != 1) {
1618: 		ht_dbg(sta->sdata,
1619: 		       "%pM just authorized and MIMO capable - update SMPS\n",
1620: 		       sta->sta.addr);
1621: 		ieee80211_send_smps_action(sta->sdata,
1622: 			sta->sdata->bss->req_smps,
1623: 			sta->sta.addr,
1624: 			sta->sdata->vif.bss_conf.bssid);
1625: 	}
1626: 
1627: 	if (sdata->vif.type == NL80211_IFTYPE_STATION &&
1628: 	    params->sta_flags_mask & BIT(NL80211_STA_FLAG_AUTHORIZED)) {
1629: 		ieee80211_recalc_ps(local, -1);
1630: 		ieee80211_recalc_ps_vif(sdata);
1631: 	}
1632: 
1633: 	return 0;
1634: out_err:
1635: 	mutex_unlock(&local->sta_mtx);
1636: 	return err;
