1598: void cfg80211_send_layer2_update(struct net_device *dev, const u8 *addr)
1599: {
1600: 	struct iapp_layer2_update *msg;
1601: 	struct sk_buff *skb;
1602: 
1603: 	/* Send Level 2 Update Frame to update forwarding tables in layer 2
1604: 	 * bridge devices */
1605: 
1606: 	skb = dev_alloc_skb(sizeof(*msg));
1607: 	if (!skb)
1608: 		return;
1609: 	msg = (struct iapp_layer2_update *)skb_put(skb, sizeof(*msg));
1610: 
1611: 	/* 802.2 Type 1 Logical Link Control (LLC) Exchange Identifier (XID)
1612: 	 * Update response frame; IEEE Std 802.2-1998, 5.4.1.2.1 */
1613: 
1614: 	eth_broadcast_addr(msg->da);
1615: 	ether_addr_copy(msg->sa, addr);
1616: 	msg->len = htons(6);
1617: 	msg->dsap = 0;
1618: 	msg->ssap = 0x01;	/* NULL LSAP, CR Bit: Response */
1619: 	msg->control = 0xaf;	/* XID response lsb.1111F101.
1620: 				 * F=0 (no poll command; unsolicited frame) */
1621: 	msg->xid_info[0] = 0x81;	/* XID format identifier */
1622: 	msg->xid_info[1] = 1;	/* LLC types/classes: Type 1 LLC */
1623: 	msg->xid_info[2] = 0;	/* XID sender's receive window size (RW) */
1624: 
1625: 	skb->dev = dev;
1626: 	skb->protocol = eth_type_trans(skb, dev);
1627: 	memset(skb->cb, 0, sizeof(skb->cb));
1628: 	netif_rx_ni(skb);
1629: }
